import 'dart:async';import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:connectivity_plus/connectivity_plus.dart';import '../app_config.dart';import '../../Core/Storage/Local/local_storage_keys.dart';import '../../Core/Storage/Local/local_storage_service.dart';class SettingsCubit extends Cubit<SettingsState> with WidgetsBindingObserver {  final Connectivity _connectivity = Connectivity();  late StreamSubscription _subscription;  SettingsCubit() : super(SettingsState(locale: AppConfig.languageMain)) {    WidgetsBinding.instance.addObserver(this);    _monitorConnection();    _updateLanguage();  }  @override  Future<void> close() {    WidgetsBinding.instance.removeObserver(this);    _subscription.cancel();    return super.close();  }  @override  void didChangePlatformBrightness() {    _updateThemeMode();  }  void _updateThemeMode() {}  void _updateLanguage() async {    final localeString = await LocalStorageService.getValue(      LocalStorageKeys.selectedLanguage,      defaultValue: false,    );    if (localeString != false) {      emit(state.copyWith(locale: Locale(localeString)));    }  }  void toggleTheme() {    emit(state.copyWith(      themeMode:          state.themeMode == ThemeMode.light ? ThemeMode.dark : ThemeMode.light,    ));  }  void changeLanguage(Locale locale) {    emit(state.copyWith(locale: locale));  }  void _monitorConnection() {    _subscription = _connectivity.onConnectivityChanged.listen((result) {      if (result.isEmpty || result.contains(ConnectivityResult.none)) {        emit(state.copyWith(internet: false));      } else {        emit(state.copyWith(internet: true));      }    });  }  bool getConnectivity() => state.internet;}@immutableclass SettingsState {  final ThemeMode themeMode;  final Locale locale;  final bool internet;  const SettingsState({    this.themeMode = ThemeMode.light,    required this.locale,    this.internet = false,  });  SettingsState copyWith({    ThemeMode? themeMode,    Locale? locale,    bool? internet,  }) {    return SettingsState(      themeMode: themeMode ?? this.themeMode,      locale: locale ?? this.locale,      internet: internet ?? this.internet,    );  }}